// Embedded base64 images to ensure images NEVER fail or display blank in any environment
export const BROKEN_STREET_LIGHT_IMG = "data:image/jpeg;base64,";
export const OVERGROWN_VEGETATION_IMG = "data:image/jpeg;base64,";
export const DAMAGED_PATHWAY_IMG = "data:image/jpeg;base64,";

import {
  BROKEN_STREET_LIGHT_2_JPEG_IMG,
  DAMAGED_PATHWAY_2_JPEG_IMG,
  DAMAGED_PATHWAY_3_JPEG_IMG,
  OVERGROWN_VEGETATION_2_JPEG_IMG
} from './allHazardPictures';

export const HAZARD_IMAGES = {
  'HZ-101': BROKEN_STREET_LIGHT_IMG,
  'HZ-102': OVERGROWN_VEGETATION_IMG,
  'HZ-103': DAMAGED_PATHWAY_IMG,
  'HZ-104': BROKEN_STREET_LIGHT_2_JPEG_IMG,
  'HZ-105': DAMAGED_PATHWAY_2_JPEG_IMG,
  'HZ-106': DAMAGED_PATHWAY_3_JPEG_IMG,
  'HZ-107': OVERGROWN_VEGETATION_2_JPEG_IMG,
  'broken-street-light': BROKEN_STREET_LIGHT_IMG,
  'broken-street-light-2': BROKEN_STREET_LIGHT_2_JPEG_IMG,
  'overgrown-vegetation': OVERGROWN_VEGETATION_IMG,
  'overgrown-vegetation-2': OVERGROWN_VEGETATION_2_JPEG_IMG,
  'damaged-pathway': DAMAGED_PATHWAY_IMG,
  'damaged-pathway-2': DAMAGED_PATHWAY_2_JPEG_IMG,
  'damaged-pathway-3': DAMAGED_PATHWAY_3_JPEG_IMG,
  'light': BROKEN_STREET_LIGHT_IMG,
  'vegetation': OVERGROWN_VEGETATION_IMG,
  'path': DAMAGED_PATHWAY_IMG
};

export function getHazardImage(hazard) {
  if (!hazard) return null;
  if (hazard.figureUrl) return hazard.figureUrl;
  if (HAZARD_IMAGES[hazard.id]) return HAZARD_IMAGES[hazard.id];
  const cat = (hazard.category || '').toLowerCase();
  const title = (hazard.title || '').toLowerCase();
  if (cat.includes('light') || title.includes('light') || title.includes('lamp')) return BROKEN_STREET_LIGHT_IMG;
  if (cat.includes('vegetation') || cat.includes('sightline') || title.includes('vegetation')) return OVERGROWN_VEGETATION_IMG;
  if (cat.includes('path') || cat.includes('pavement') || title.includes('path') || title.includes('crack')) return DAMAGED_PATHWAY_IMG;
  return hazard.figureUrl || BROKEN_STREET_LIGHT_IMG;
}